import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"游戏的保存与加载","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tutorials/Save_Load.md","filePath":"guide/tutorials/Save_Load.md"}`),a={name:`guide/tutorials/Save_Load.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="游戏的保存与加载" tabindex="-1">游戏的保存与加载 <a class="header-anchor" href="#游戏的保存与加载" aria-label="Permalink to “游戏的保存与加载”">​</a></h1><h2 id="前言与确认" tabindex="-1">前言与确认 <a class="header-anchor" href="#前言与确认" aria-label="Permalink to “前言与确认”">​</a></h2><p>玩家长时间培养的角色、攒下的金币、推进的剧情……如果关掉游戏就全没了，那也太惨了。所以，<strong>存档</strong>是任何一款游戏都绕不开的功能。这一节，我们让游戏学会“记住”和“想起来”。</p><div class="warning custom-block"><p class="custom-block-title">教程依赖</p><p>本教程假设您已学习过<a href="./../Quick_Start.html">快速开始</a>、<a href="./Compound_Statement.html">复合语句</a>和<a href="./Function.html">函数的定义与用法</a>。若您尚未学习过，我们强烈推荐您首先学习相应教程。</p></div><p>先确认一下我们现有的工程文件夹结构：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>root/</span></span>
<span class="line"><span> ├─ emuera.config</span></span>
<span class="line"><span> ├─ Emuera1824.exe</span></span>
<span class="line"><span> ├─ CSV/</span></span>
<span class="line"><span> └─ ERB/</span></span>
<span class="line"><span>     └─ System.erb</span></span></code></pre></div><p>其中，<code>System.erb</code>的代码为：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  Print</span><span style="color:#9CDCFE;"> Hello</span><span style="color:#9CDCFE;"> World</span><span style="color:#D4D4D4;">!</span></span>
<span class="line"><span style="color:#569CD6;">  Quit</span></span></code></pre></div><h2 id="存档就是把-现在的状态-写下来" tabindex="-1">存档就是把“现在的状态”写下来 <a class="header-anchor" href="#存档就是把-现在的状态-写下来" aria-label="Permalink to “存档就是把“现在的状态”写下来”">​</a></h2><p>Emuera 会自动记录所有变量的值。所谓存档，就是把这套“当前状态”写进一个文件；读档则是把文件里的状态读回来，覆盖当前的状态。</p><p>Emuera 提供了两套做法：</p><ul><li><strong>直接存档</strong>：自己给存档编号，用 <code>SAVEDATA</code> / <code>LOADDATA</code>，简单直接；</li><li><strong>标准存档界面</strong>：用 <code>SAVEGAME</code> / <code>LOADGAME</code> 呼出引擎自带的存档/读档画面。</li></ul><p>先学第一套，它更好理解。</p><h2 id="一个能存能读的小游戏" tabindex="-1">一个能存能读的小游戏 <a class="header-anchor" href="#一个能存能读的小游戏" aria-label="Permalink to “一个能存能读的小游戏”">​</a></h2><p>把下面的代码写进 <code>System.erb</code>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">EventFirst</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Money</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 100</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> Day</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">  #</span><span style="color:#C586C0;">Dim</span><span style="color:#9CDCFE;"> QuitFlag</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C586C0;">  WHILE</span><span style="color:#9CDCFE;"> QuitFlag</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">    CLEARLINE</span><span style="color:#9CDCFE;"> LINECOUNT</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#D4D4D4;"> ==============================</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#9CDCFE;"> 第</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTV</span><span style="color:#9CDCFE;"> Day</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#9CDCFE;"> 天</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#9CDCFE;"> 金币：</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTV</span><span style="color:#9CDCFE;"> Money</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#E6E6E6;"> [</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">] </span><span style="color:#9CDCFE;">打工赚</span><span style="color:#B5CEA8;"> 10</span><span style="color:#9CDCFE;"> 金币</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#E6E6E6;"> [</span><span style="color:#B5CEA8;">1</span><span style="color:#E6E6E6;">] </span><span style="color:#9CDCFE;">保存游戏</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#E6E6E6;"> [</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">] </span><span style="color:#9CDCFE;">读取游戏</span></span>
<span class="line"><span style="color:#569CD6;">    PRINTL</span><span style="color:#E6E6E6;"> [</span><span style="color:#B5CEA8;">3</span><span style="color:#E6E6E6;">] </span><span style="color:#9CDCFE;">退出</span></span>
<span class="line"><span style="color:#569CD6;">    INPUT</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C586C0;">    SELECTCASE</span><span style="color:#9CDCFE;"> RESULT</span></span>
<span class="line"><span style="color:#C586C0;">      CASE</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#9CDCFE;">        Money</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 10</span></span>
<span class="line"><span style="color:#9CDCFE;">        Day</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#C586C0;">      CASE</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">        SAVEDATA</span><span style="color:#B5CEA8;"> 0</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;第 &quot;</span><span style="color:#D4D4D4;"> +</span><span style="color:#DCDCAA;"> TOSTR</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">Day</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">+</span><span style="color:#CE9178;"> &quot; 天&quot;</span></span>
<span class="line"><span style="color:#569CD6;">        PRINTL</span><span style="color:#9CDCFE;"> 保存成功！</span></span>
<span class="line"><span style="color:#569CD6;">        WAIT</span></span>
<span class="line"><span style="color:#C586C0;">      CASE</span><span style="color:#B5CEA8;"> 2</span></span>
<span class="line"><span style="color:#9CDCFE;">        CHKDATA</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#C586C0;">        IF</span><span style="color:#9CDCFE;"> RESULT</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">          LOADDATA</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#569CD6;">          PRINTL</span><span style="color:#9CDCFE;"> 读取成功！</span></span>
<span class="line"><span style="color:#C586C0;">        ELSE</span></span>
<span class="line"><span style="color:#569CD6;">          PRINTL</span><span style="color:#9CDCFE;"> 存档不存在或无法读取。</span></span>
<span class="line"><span style="color:#C586C0;">        ENDIF</span></span>
<span class="line"><span style="color:#569CD6;">        WAIT</span></span>
<span class="line"><span style="color:#C586C0;">      CASE</span><span style="color:#B5CEA8;"> 3</span></span>
<span class="line"><span style="color:#9CDCFE;">        QuitFlag</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#C586C0;">      CASEELSE</span></span>
<span class="line"><span style="color:#6A9955;">        ; 无效输入，什么都不做，重新循环</span></span>
<span class="line"><span style="color:#C586C0;">    ENDSELECT</span></span>
<span class="line"><span style="color:#C586C0;">  WEND</span></span>
<span class="line"><span style="color:#569CD6;">  QUIT</span></span></code></pre></div><p>运行后，你可以打工攒金币、随时保存、退出再进来读取，进度都还在。</p><h2 id="三个关键命令" tabindex="-1">三个关键命令 <a class="header-anchor" href="#三个关键命令" aria-label="Permalink to “三个关键命令”">​</a></h2><h3 id="savedata-保存" tabindex="-1">SAVEDATA：保存 <a class="header-anchor" href="#savedata-保存" aria-label="Permalink to “SAVEDATA：保存”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">SAVEDATA</span><span style="color:#B5CEA8;"> 0</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;第 &quot;</span><span style="color:#D4D4D4;"> +</span><span style="color:#DCDCAA;"> TOSTR</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">Day</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">+</span><span style="color:#CE9178;"> &quot; 天&quot;</span></span></code></pre></div><ul><li>第 1 个参数是<strong>存档编号</strong>（0 到 19 左右，取决于配置）；</li><li>第 2 个参数是<strong>存档简介</strong>，会显示在读取列表里。</li></ul><p>第二个参数是字符串表达式，所以可以像上面那样把天数拼进去。如果写 <code>SAVEDATA 0</code> 而不给简介，也可以，只是读取列表里就看不到信息了。</p><h3 id="chkdata-先检查-再读取" tabindex="-1">CHKDATA：先检查，再读取 <a class="header-anchor" href="#chkdata-先检查-再读取" aria-label="Permalink to “CHKDATA：先检查，再读取”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">CHKDATA</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#C586C0;">IF</span><span style="color:#9CDCFE;"> RESULT</span><span style="color:#D4D4D4;"> ==</span><span style="color:#B5CEA8;"> 0</span></span>
<span class="line"><span style="color:#6A9955;">  ; 可以读取</span></span>
<span class="line"><span style="color:#C586C0;">ENDIF</span></span></code></pre></div><p><code>CHKDATA</code> 会检查指定编号的存档能不能读，把结果放进 <code>RESULT</code>：</p><ul><li><code>0</code>：可以读取；</li><li>非 <code>0</code>：不存在、版本不符等原因导致不可读取。</li></ul><p><strong>读取前一定要先检查</strong>，因为 <code>LOADDATA</code> 失败是会直接报错的。</p><h3 id="loaddata-读取" tabindex="-1">LOADDATA：读取 <a class="header-anchor" href="#loaddata-读取" aria-label="Permalink to “LOADDATA：读取”">​</a></h3><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">LOADDATA</span><span style="color:#B5CEA8;"> 0</span></span></code></pre></div><p>读档成功后，所有变量的值都会变成存档里的样子——包括我们用来控制循环的 <code>QuitFlag</code>。好在存档时它就是 0，所以读档后循环会自然继续。</p><h2 id="另一种方式-标准存档界面" tabindex="-1">另一种方式：标准存档界面 <a class="header-anchor" href="#另一种方式-标准存档界面" aria-label="Permalink to “另一种方式：标准存档界面”">​</a></h2><p>如果你希望玩家看到引擎自带的那个漂亮的存档列表，可以用：</p><ul><li><code>SAVEGAME</code>：呼出保存界面；</li><li><code>LOADGAME</code>：呼出读取界面；</li><li><code>@SAVEINFO</code>：引擎在生成每条存档简介时自动调用的函数。</li></ul><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">SAVEINFO</span></span>
<span class="line"><span style="color:#569CD6;">  PUTFORM</span><span style="color:#E6E6E6;"> 第 </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">Day</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;"> 天　金币 </span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">Money</span><span style="color:#569CD6;">}</span></span>
<span class="line"><span style="color:#C586C0;">  RETURN</span></span></code></pre></div><p><code>PUTFORM</code> 会用与 <code>PRINTFORM</code> 类似的方式，把当前进度写进存档简介。这样玩家就能一眼看出每个存档里是什么情况。</p><blockquote><p><code>SAVEGAME</code> 和 <code>LOADGAME</code> 只能在商店（<code>SHOP</code>）流程中调用，这一点和可以随处调用的 <code>SAVEDATA</code> / <code>LOADDATA</code> 不同。具体细节可以查阅<a href="./../../translation/Command.html">命令</a>中的相应条目。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><ul><li>存档把“当前状态”写进文件，读档再读回来；</li><li><code>SAVEDATA &lt;编号&gt;, &lt;简介&gt;</code> 保存，<code>LOADDATA &lt;编号&gt;</code> 读取；</li><li>读取前先用 <code>CHKDATA</code> 检查，避免报错；</li><li>想使用引擎自带界面，就用 <code>SAVEGAME</code> / <code>LOADGAME</code>，并配合 <code>@SAVEINFO</code> 写简介。</li></ul><p>下一步，我们来看看程序出错时该怎么办：<a href="./Error.html">错误与异常</a>。</p>`,39)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};